-- ENT Obstructive Sleep Apnea MCQs (Part 4/6)
-- Target platform: Supabase (Postgres)
-- Topic Slug: ent-sleep-apnea

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ent-sleep-apnea' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ent-sleep-apnea not found.';
    END IF;

    ;

END $$;
COMMIT;
